void main() {
  vec2 uv = gl_FragCoord.xy / u_resolution;
  float d = length(uv - 0.5);
  float ring = smoothstep(0.02, 0.0, abs(d - 0.25 - 0.05 * sin(u_time * 2.0)));
  vec3 col = mix(vec3(0.05, 0.07, 0.12), vec3(0.4, 0.8, 1.0), ring);
  col += 0.15 * vec3(uv.x, uv.y, 0.6);
  gl_FragColor = vec4(col, 1.0);
}

// vertex
attribute vec3 aPos;
attribute vec2 aUV;
varying vec2 vUV;
uniform mat4 uMVP;
void main() {
  vUV = aUV;
  gl_Position = uMVP * vec4(aPos, 1.0);
}

// fragment
precision mediump float;
varying vec2 vUV;
uniform float uTime;
void main() {
  vec3 col = 0.5 + 0.5 * cos(uTime + vUV.xyx + vec3(0.0, 2.0, 4.0));
  gl_FragColor = vec4(col, 1.0);
}
